from time import time
STEPUP_REQUIRED = {"transfer:write", "secret:read", "admin:*"}
MAX_STEPUP_AGE_SEC = 600  # 10 minutes of strong-proof freshness

def authorize(token_claims: dict, required_scope: str):
    # token_claims comes from verified JWT: sub, scope, amr, acr, auth_time
    if required_scope not in token_claims.get("scope", []):
        return (False, "deny: missing scope")

    if required_scope not in STEPUP_REQUIRED:
        return (True, "allow: low-risk scope")

    amr = set(token_claims.get("amr", []))
    acr = int(token_claims.get("acr", 0))
    auth_time = int(token_claims.get("auth_time", 0))

    # Require possession proof in addition to password, at high assurance.
    if acr < 2 or not (amr & {"otp", "push", "hwk"}):
        return (False, "step_up_required: need second factor")
    if time() - auth_time > MAX_STEPUP_AGE_SEC:
        return (False, "step_up_required: proof too old")
    return (True, "allow: fresh strong proof")
